// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"AP Physics 2 starts with heat and gases, explaining big-scale behavior from tiny particle motion.","blocks":[{"t":"key","text":"Ideal gas law: PV = nRT = NkT. Temperature is proportional to the average kinetic energy of particles: K_avg = (3/2)kT."},{"t":"p","text":"Pressure comes from particles colliding with container walls. At higher temperature, particles move faster and collide harder and more often."},{"t":"p","text":"On a PV diagram, isothermal processes stay at constant temperature, isobaric at constant pressure, isochoric (isovolumetric) at constant volume, and adiabatic with no heat exchange."},{"t":"ex","problem":"A gas at 300 K is heated to 600 K at constant volume. What happens to its pressure?","steps":["P/T is constant at fixed V and n"],"answer":"Pressure doubles"}]},{"say":"The laws of thermodynamics govern every engine, refrigerator and living thing.","blocks":[{"t":"key","text":"First law: ΔU = Q + W, where Q is heat added to the system and W is work done ON the system. Energy is conserved."},{"t":"p","text":"Work done on a gas equals the negative of the area under its PV curve (W = −PΔV for constant pressure). Expanding gas does work on its surroundings, so W on the gas is negative."},{"t":"p","text":"Second law: heat flows naturally from hot to cold, and the entropy of an isolated system never decreases. No heat engine can be 100% efficient."},{"t":"p","text":"Heat transfers by conduction (contact), convection (fluid motion) and radiation (electromagnetic waves)."},{"t":"ex","problem":"A gas absorbs 500 J of heat and does 200 J of work on its surroundings. Find ΔU.","steps":["Q = +500 J; W on the gas = −200 J"],"answer":"ΔU = 300 J"}]}],[{"say":"Charges push and pull each other. Electric fields describe how a charge affects the space around it.","blocks":[{"t":"key","text":"Coulomb's law: F = k|q₁q₂|/r². Like charges repel; opposite charges attract. Doubling the distance makes the force 1/4 as strong."},{"t":"p","text":"The electric field E = F/q is the force per unit charge. Field lines point away from positive charges and toward negative charges. A uniform field exists between parallel charged plates."},{"t":"ex","problem":"Two charges are 2 m apart with force 36 N. They move to 6 m apart. New force?","steps":["Distance tripled, so force ÷ 9"],"answer":"4 N"},{"t":"p","text":"Charge is conserved and quantized (multiples of e = 1.6 × 10⁻¹⁹ C). Conductors let charge move freely; charge on a conductor sits on its surface."}]},{"say":"Electric potential is like height for charges. Charges \"fall\" from high potential to low potential.","blocks":[{"t":"key","text":"Electric potential V = U/q (volts). The potential difference ΔV drives charges. In a uniform field, ΔV = Ed."},{"t":"p","text":"Work done moving a charge: W = qΔV. Equipotential lines are perpendicular to field lines; moving along them takes no work."},{"t":"p","text":"A capacitor stores charge and energy: C = Q/V. For parallel plates, C = κε₀A/d. Energy stored: U = ½CV²."},{"t":"ex","problem":"A capacitor of 4 μF is charged to 10 V. How much charge and energy does it store?","steps":["Q = CV = 4 × 10⁻⁶ × 10 = 4 × 10⁻⁵ C"],"answer":"U = ½(4 × 10⁻⁶)(10²) = 2 × 10⁻⁴ J"}]}],[{"say":"Circuits put moving charge to work. Let's connect current, voltage and resistance.","blocks":[{"t":"key","text":"Current I = ΔQ/Δt. Ohm's law: V = IR. Resistance R = ρL/A: longer, thinner wires and higher resistivity mean more resistance."},{"t":"p","text":"Power P = IV = I²R = V²/R. Batteries provide emf; real batteries have internal resistance, so terminal voltage drops when current flows."},{"t":"ex","problem":"A 12 V battery drives current through a 6 Ω resistor. Find current and power.","steps":["I = 12/6 = 2 A"],"answer":"P = 2 × 12 = 24 W"},{"t":"p","text":"Current is conserved at junctions (Kirchhoff's junction rule), and the voltage changes around any closed loop sum to zero (loop rule)."}]},{"say":"How components are connected changes how current and voltage divide. Capacitors add time-dependent behavior.","blocks":[{"t":"key","text":"Series resistors: R_eq = R₁ + R₂ (same current). Parallel resistors: 1/R_eq = 1/R₁ + 1/R₂ (same voltage). Capacitors combine the opposite way: parallel add, series add reciprocally."},{"t":"p","text":"Adding a resistor in parallel lowers total resistance and increases total current from the battery."},{"t":"p","text":"RC circuits: when charging, current starts high and decreases as the capacitor fills. After a long time, a charged capacitor acts like an open circuit (no current through its branch)."},{"t":"ex","problem":"Find R_eq for 6 Ω and 3 Ω in parallel.","steps":["1/R = 1/6 + 1/3 = 1/2"],"answer":"R_eq = 2 Ω"}]}],[{"say":"Moving charges create magnetic fields and feel magnetic forces. That's how motors work.","blocks":[{"t":"key","text":"Force on a moving charge: F = qvB sin θ. Force on a current-carrying wire: F = ILB sin θ. Use the right-hand rule to find direction."},{"t":"p","text":"The magnetic force is perpendicular to velocity, so it changes direction but does no work. A charge moving perpendicular to a uniform field travels in a circle: r = mv/(qB)."},{"t":"p","text":"A long straight wire creates a magnetic field circling it: B = μ₀I/(2πr). Parallel currents in the same direction attract."},{"t":"ex","problem":"An electron and a proton enter the same magnetic field at the same speed. How do their paths differ?","steps":["Opposite charges curve in opposite directions"],"answer":"They curve opposite ways; the lighter electron curves in a much smaller circle"}]},{"say":"Changing magnetic fields create electric currents. This discovery powers our entire electrical grid.","blocks":[{"t":"key","text":"Magnetic flux Φ = BA cos θ. Faraday's law: emf = −NΔΦ/Δt. A changing flux induces an emf."},{"t":"p","text":"Lenz's law: the induced current flows to oppose the change in flux (the minus sign). Flux can change by changing B, the area, or the orientation."},{"t":"p","text":"A conducting rod moving through a field has motional emf = BLv."},{"t":"p","text":"Generators spin coils in magnetic fields; transformers change voltages using induction between coils."},{"t":"ex","problem":"A loop's flux increases. Which way does the induced current flow?","steps":["Lenz's law: the induced field must oppose the increase"],"answer":"It flows in the direction that creates a field opposite to the increasing external field"}]}],[{"say":"Light travels in straight lines and bounces predictably. Mirrors use this to form images.","blocks":[{"t":"key","text":"Law of reflection: angle of incidence = angle of reflection. Mirror and lens equation: 1/f = 1/dₒ + 1/dᵢ. Magnification M = −dᵢ/dₒ."},{"t":"p","text":"Concave mirrors converge light (f > 0). Objects beyond the focal point form real, inverted images; objects inside f form virtual, upright, enlarged images. Convex mirrors always form virtual, upright, smaller images."},{"t":"p","text":"Ray diagrams use special rays: parallel to the axis reflects through the focal point; through the focal point reflects parallel."},{"t":"ex","problem":"An object is 30 cm from a concave mirror with f = 10 cm. Where is the image?","steps":["1/dᵢ = 1/10 − 1/30 = 2/30"],"answer":"dᵢ = 15 cm (real, inverted, half size)"}]},{"say":"Light bends when it changes speed between materials. Lenses use this bending to focus light.","blocks":[{"t":"key","text":"Index of refraction n = c/v. Snell's law: n₁ sin θ₁ = n₂ sin θ₂. Light bends toward the normal entering a higher-n material."},{"t":"p","text":"Total internal reflection occurs when light goes from high n to low n at an angle greater than the critical angle: sin θc = n₂/n₁."},{"t":"p","text":"Converging (convex) lenses have positive f; diverging (concave) lenses have negative f. The same thin-lens equation 1/f = 1/dₒ + 1/dᵢ applies."},{"t":"ex","problem":"Light enters glass (n = 1.5) from air at 30°. Find the refraction angle.","steps":["1.0 sin 30° = 1.5 sin θ₂","sin θ₂ = 0.333"],"answer":"θ₂ ≈ 19.5°"}]}],[{"say":"Waves carry energy without carrying matter. Sound waves show these properties clearly.","blocks":[{"t":"key","text":"v = fλ. Wave speed depends on the medium, not the frequency. Sound is a longitudinal mechanical wave; it travels faster in solids than in gases."},{"t":"p","text":"Standing waves form from interference of reflected waves. On a string fixed at both ends, λ = 2L/n. Open pipes support all harmonics; closed pipes (closed at one end) support only odd harmonics: λ = 4L/n for odd n."},{"t":"p","text":"Doppler effect: a source moving toward you sounds higher in frequency; moving away, lower."},{"t":"p","text":"Beats occur when two close frequencies interfere: f_beat = |f₁ − f₂|."},{"t":"ex","problem":"Two tuning forks at 440 Hz and 444 Hz sound together. What do you hear?","steps":["Beat frequency = |440 − 444|"],"answer":"4 beats per second"}]},{"say":"Light behaves as a wave when it passes through slits. Interference patterns proved it.","blocks":[{"t":"key","text":"Double-slit interference: bright fringes where d sin θ = mλ. The fringe spacing on a screen is about Δy = λL/d."},{"t":"p","text":"Path difference determines interference: whole wavelengths give constructive interference (bright); half wavelengths give destructive (dark)."},{"t":"p","text":"Single-slit diffraction spreads light, with a wide central maximum. Diffraction gratings with many slits make sharp, widely separated bright lines."},{"t":"p","text":"Thin-film interference (soap bubbles, oil slicks) comes from light reflecting off both surfaces of a film; reflections off higher-n surfaces shift phase by half a wavelength."},{"t":"ex","problem":"In a double-slit setup, what happens to the fringes if the slits move closer together?","steps":["Δy = λL/d, so smaller d gives larger Δy"],"answer":"The fringes spread farther apart"}]}],[{"say":"Around 1900, experiments showed that light comes in packets and matter behaves like waves. Welcome to quantum physics.","blocks":[{"t":"key","text":"Photon energy E = hf = hc/λ. In the photoelectric effect, K_max = hf − φ, where φ is the work function."},{"t":"p","text":"Increasing light intensity increases the number of ejected electrons but not their maximum kinetic energy. Below the threshold frequency, no electrons are ejected, no matter how bright the light."},{"t":"p","text":"Matter has wave properties too: de Broglie wavelength λ = h/p. Electron diffraction confirmed this."},{"t":"p","text":"Atoms have discrete energy levels; electrons emit or absorb photons when they jump between levels, producing line spectra unique to each element."},{"t":"ex","problem":"A metal has φ = 2.0 eV. Light with photon energy 5.0 eV hits it. Find K_max.","steps":["K_max = 5.0 − 2.0"],"answer":"3.0 eV"}]},{"say":"The nucleus holds enormous energy. Nuclear reactions convert tiny amounts of mass into huge amounts of energy.","blocks":[{"t":"key","text":"E = mc². The mass defect (mass of separate nucleons minus the nucleus's mass) corresponds to the binding energy holding the nucleus together."},{"t":"p","text":"Radioactive decay:"},{"t":"list","items":["Alpha: emits a helium nucleus (mass number −4, atomic number −2).","Beta-minus: a neutron becomes a proton, emitting an electron and antineutrino (atomic number +1).","Gamma: emits high-energy photons with no change in particles."]},{"t":"p","text":"Conservation laws hold in nuclear reactions: charge, nucleon number, energy and momentum."},{"t":"p","text":"Fission splits heavy nuclei; fusion combines light nuclei. Both release energy because the products are more tightly bound."},{"t":"ex","problem":"Uranium-238 (Z = 92) undergoes alpha decay. What nucleus results?","steps":["Mass number 238 − 4 = 234; Z = 92 − 2 = 90"],"answer":"Thorium-234"}]}]];
export default text;
